(982244, 116702, 23478, '<td valign="top">NIce photo.</td>', 'NIce photo.', '2004-11-01 00:48:51.000000', NULL, 1),
(982246, 116740, 22537, '<td valign="top">Excellent shot.</td>', 'Excellent shot.', '2004-11-01 00:49:05.000000', NULL, 1),
