(982259, 117207, 23478, '<td valign="top">Wow, this is cool.  I really like it.</td>', 'Wow, this is cool.  I really like it.', '2004-11-01 00:51:57.000000', NULL, 1),
(982260, 113480, 22537, '<td valign="top">This is very striking.</td>', 'This is very striking.', '2004-11-01 00:52:00.000000', NULL, 1),
