(982610, 111744, 22781, '<td valign="top">I gasped when I saw this shot. WOW (10)</td>', 'I gasped when I saw this shot. WOW (10)', '2004-11-01 06:26:52.000000', NULL, 1),
(982613, 117083, 23478, '<td valign="top">Interesting shot, the colors are great.</td>', 'Interesting shot, the colors are great.', '2004-11-01 06:28:29.000000', NULL, 1),
(982614, 117212, 17492, '<td valign="top">Great title.</td>', 'Great title.', '2004-11-01 06:29:31.000000', NULL, 1),
