(984140, 116364, 9780, '<td valign="top">Hee is lucky that you did just shust some photos of him.;) .. nice framing</td>', 'Hee is lucky that you did just shust some photos of him.;) .. nice framing', '2004-11-01 19:07:21.000000', NULL, 1),
(984143, 115846, 1368, '<td valign="top">Very cool :D I love the sky and the colors in the picture Good job</td>', 'Very cool :D I love the sky and the colors in the picture Good job', '2004-11-01 19:07:38.000000', NULL, 1),
(984147, 114484, 1368, '<td valign="top">Beautiful lighting Beautiful  composition Amazing picture I love it :D</td>', 'Beautiful lighting Beautiful  composition Amazing picture I love it :D', '2004-11-01 19:08:55.000000', NULL, 1),
