(984985, 111788, 19982, '<td valign="top">Love the colors.  As an abstract, this photo works perfectly.  Still, I kinda wish for a "subject" (a center of attention ... something to focus on).  Good luck in the challenge.</td>', 'Love the colors.  As an abstract, this photo works perfectly.  Still, I kinda wish for a "subject" (a center of attention ... something to focus on).  Good luck in the challenge.', '2004-11-02 00:37:46.000000', NULL, 1),
(985015, 114842, 16241, '<td valign="top">this would have looked great in black white as well.</td>', 'this would have looked great in black white as well.', '2004-11-02 01:11:45.000000', NULL, 1),
(985020, 109332, 16241, '<td valign="top">certianly catches your eye out of all the thumbnails, think you may<br/>get same with the title tho.<br/>clever</td>', 'certianly catches your eye out of all the thumbnails, think you mayget same with the title tho.clever', '2004-11-02 01:18:54.000000', NULL, 1),
(985022, 114432, 16241, '<td valign="top">was the date intentional?   bet you get lotsacomments on this one</td>', 'was the date intentional?   bet you get lotsacomments on this one', '2004-11-02 01:19:36.000000', NULL, 1),
(985023, 116882, 16241, '<td valign="top">thanks but no thanks :)<br/> <br/>nice &amp; clear</td>', 'thanks but no thanks :) nice & clear', '2004-11-02 01:20:19.000000', NULL, 1),
