(985168, 116643, 22781, '<td valign="top">Great high key photo, well executed.</td>', 'Great high key photo, well executed.', '2004-11-02 03:13:02.000000', NULL, 1),
(985169, 112238, 23478, '<td valign="top">NIce portrait, maybe could have cropped it  little closer top and bottom.</td>', 'NIce portrait, maybe could have cropped it  little closer top and bottom.', '2004-11-02 03:13:11.000000', NULL, 1),
