(985235, 115958, 20608, '<td valign="top">Mad Max jumps to mind, nice wide angle shot</td>', 'Mad Max jumps to mind, nice wide angle shot', '2004-11-02 04:28:18.000000', NULL, 1),
(985238, 117283, 20608, '<td valign="top">as a musician i can go with this great choice for B&amp;W</td>', 'as a musician i can go with this great choice for B&W', '2004-11-02 04:29:32.000000', NULL, 1),
(985240, 116170, 20608, '<td valign="top">intentionally grainy? cute kid though</td>', 'intentionally grainy? cute kid though', '2004-11-02 04:30:18.000000', NULL, 1),
(985241, 116124, 20608, '<td valign="top">you might of wanted to use a polorizer to stop the light scorching it out.. iv''e tried these type of shots and failed they aint easy</td>', 'you might of wanted to use a polorizer to stop the light scorching it out.. iv''e tried these type of shots and failed they aint easy', '2004-11-02 04:31:28.000000', NULL, 1),
