(988231, 116948, 22781, '<td valign="top">I would be afraid to fall off..</td>', 'I would be afraid to fall off..', '2004-11-03 08:11:17.000000', NULL, 1),
(988232, 116187, 22781, '<td valign="top">I wonder how you guy''s manage these great macro photo''s</td>', 'I wonder how you guy''s manage these great macro photo''s', '2004-11-03 08:11:49.000000', NULL, 1),
(988233, 114394, 22781, '<td valign="top">Just beautifull....</td>', 'Just beautifull....', '2004-11-03 08:12:05.000000', NULL, 1),
(988235, 117150, 22781, '<td valign="top">Could have done with just a bit more saturation I guess</td>', 'Could have done with just a bit more saturation I guess', '2004-11-03 08:12:30.000000', NULL, 1),
