(988630, 117217, 327, '<td valign="top">Would of only liked the lamp not so tilted. Over all this is one fine shot. Nice going.</td>', 'Would of only liked the lamp not so tilted. Over all this is one fine shot. Nice going.', '2004-11-03 11:24:10.000000', NULL, 1),
(988631, 117285, 14476, '<td valign="top">The colors set this beautifully composition above the rest.  Well done.  10</td>', 'The colors set this beautifully composition above the rest.  Well done.  10', '2004-11-03 11:24:15.000000', NULL, 1),
