(989139, 111183, 24911, '<td valign="top">What a great shot! Amazing subject. Good composition. 9.</td>', 'What a great shot! Amazing subject. Good composition. 9.', '2004-11-03 14:42:18.000000', NULL, 1),
(989140, 115279, 25143, '<td valign="top">excellent - focus choice , color contrasts ... very intriguing overall</td>', 'excellent - focus choice , color contrasts ... very intriguing overall', '2004-11-03 14:43:35.000000', NULL, 1),
